async function openAccount(){if(!requireSession())return;$('#accountView').innerHTML='Hesap yükleniyor…';accountDialog.showModal();try{const [profile,works,library]=await Promise.all([sb(`/rest/v1/profiles?select=display_name,username,bio,is_admin&id=eq.${session.user.id}`),sb(`/rest/v1/stories?select=id,title,genre,status,read_count&author_id=eq.${session.user.id}&order=updated_at.desc`),sb(`/rest/v1/library_items?select=story_id,progress,updated_at&user_id=eq.${session.user.id}&order=updated_at.desc`)]),p=profile?.[0],storyMap=Object.fromEntries(stories.map(s=>[s.id,s])),historyItems=(library||[]).filter(i=>i.progress>0&&storyMap[i.story_id]).slice(0,6);currentProfile=p;$('#accountView').innerHTML=`<div class="profile-card"><div class="profile-avatar">${esc((p?.display_name||session.user.email)[0].toUpperCase())}</div><h3>${esc(p?.display_name||'Fasl kullanıcısı')}</h3><span>@${esc(p?.username||'kullanici')}</span><div class="profile-stats"><b>${works?.length||0}<small>Hikâye</small></b><b>${library?.length||0}<small>Kütüphane</small></b></div><div class="account-primary-actions"><button class="ink" data-new-story>+ Yeni hikâye oluştur</button>${p?.is_admin?'<button class="ghost" data-admin>Yönetici paneli</button>':''}</div></div><section class="reading-history"><h3>Okuma geçmişim</h3><div>${historyItems.length?historyItems.map(i=>{const s=storyMap[i.story_id];return `<button data-resume-story="${s.id}"><span><b>${esc(s.title)}</b><small>${esc(s.author)} · %${i.progress} okundu</small></span><i style="--progress:${i.progress}%"></i><strong>Devam et →</strong></button>`}).join(''):'<p>Henüz okumaya başladığın bir kitap yok.</p>'}</div></section><details class="profile-edit"><summary>Profili düzenle</summary><form id="profileForm"><label>Görünen ad<input name="display_name" maxlength="60" required value="${esc(p?.display_name||'')}"></label><label>Kullanıcı adı<input name="username" minlength="3" maxlength="24" pattern="[a-z0-9_]+" required value="${esc(p?.username||'')}"></label><label>Hakkımda<textarea name="bio" maxlength="300">${esc(p?.bio||'')}</textarea></label><p class="form-message" id="profileMessage"></p><button class="ink">Değişiklikleri kaydet</button></form></details><section class="my-books"><h3>Kendi Kitaplarım</h3><div class="my-book-list">${works?.length?works.map(w=>`<article><div><b>${esc(w.title)}</b><span>${esc(w.genre)} · ${storyStatus(w.status)} · ◉ ${w.read_count||0}</span></div><button class="ghost" data-manage="${w.id}" data-tab="edit">Düzenle</button><button class="ink" data-manage="${w.id}" data-tab="continue">Yazmaya devam et</button><button class="danger-button" data-delete-book="${w.id}" data-book-title="${esc(w.title)}">Sil</button></article>`).join(''):'<p>Henüz bir kitap yayımlamadın.</p>'}</div></section><button class="ghost danger account-logout" data-logout>Çıkış yap</button>`}catch(err){$('#accountView').innerHTML=`<div class="session-error"><p>${esc(err.message)}</p><button class="ink" data-session-login>Tekrar giriş yap</button><button class="ghost" data-logout>Çıkış yap</button></div>`}}
async function openManage(id,tab='edit'){if(accountDialog.open){manageDialog._returnDialog=accountDialog;accountDialog.close()}if(!manageDialog.open)manageDialog.showModal();$('#manageView').innerHTML='<p class="reader-loading">Kitap hazırlanıyor…</p>';try{const [book,chapters]=await Promise.all([sb(`/rest/v1/stories?select=id,title,summary,genre,tags,status,cover_url,trailer_url&author_id=eq.${session.user.id}&id=eq.${id}`),sb(`/rest/v1/chapters?select=id,title,position,created_at&story_id=eq.${id}&order=position.asc`)]);if(!book?.[0])throw new Error('Bu kitap bulunamadı.');manageState={book:book[0],chapters:chapters||[]};renderManage(tab)}catch(err){$('#manageView').innerHTML=`<p class="reader-loading">${esc(err.message)}</p>`}}
function renderManage(tab='edit'){const {book,chapters}=manageState;$('#manageView').innerHTML=`<div class="manage-head"><span class="mini-brand">fasl.</span><h2>${esc(book.title)}</h2><div class="tabs"><button data-manage-tab="edit" class="${tab==='edit'?'active':''}">Kitabı düzenle</button><button data-manage-tab="continue" class="${tab==='continue'?'active':''}">Yazmaya devam et</button></div></div><section class="manage-pane" ${tab==='edit'?'':'hidden'}><form id="bookEditForm"><div class="cover-upload"><div id="coverPreview" class="cover-preview ${safeCover(book.cover_url)?'has-cover-image':''}" ${safeCover(book.cover_url)?`style="background-image:url('${esc(book.cover_url)}')"`:''}><span>${esc(book.title.slice(0,1))}</span></div><div><b>Kitap kapağı</b><p>Dikey JPG, PNG veya WebP · en fazla 8 MB</p><label class="ghost cover-file-button">Kapak seç<input id="coverInput" type="file" accept="image/jpeg,image/png,image/webp" hidden></label>${safeCover(book.cover_url)?'<button type="button" class="text-btn danger" data-remove-cover>Kapağı kaldır</button>':''}</div></div><label>Kitabın adı<input name="title" maxlength="100" required value="${esc(book.title)}"></label><label>Tür<input name="genre" maxlength="40" required value="${esc(book.genre)}"></label><label>Kitabın durumu<select name="status"><option value="ongoing" ${book.status==='ongoing'?'selected':''}>Devam ediyor</option><option value="completed" ${book.status==='completed'?'selected':''}>Tamamlandı</option></select></label><label>Özet<textarea name="summary" maxlength="1200">${esc(book.summary)}</textarea></label><p class="form-message" id="bookEditMessage"></p><button class="ink">Kitabı kaydet</button></form></section><section class="manage-pane" ${tab==='continue'?'':'hidden'}><div class="chapter-list"><h3>Fasıllar</h3>${chapters.map(c=>`<div><b>${c.position}. ${esc(c.title)}</b></div>`).join('')||'<p>Henüz fasıl yok.</p>'}</div><form id="continueForm"><div class="draft-status"><span id="chapterWordCount">0 kelime</span><span id="chapterSaveState">Yeni taslak</span></div><label>Yeni faslın adı<input name="title" maxlength="120" required value="${chapters.length+1}. Fasıl"></label><label>Yeni fasıl<textarea name="content" maxlength="100000" required placeholder="Hikâyene devam et…"></textarea></label><p class="form-message" id="continueMessage"></p><button class="ink">Faslı yayımla →</button></form></section>`;if(tab==='edit')enhanceContentSettings();if(tab==='continue')restoreChapterDraft()}
function contentMeta(tags=[]){const ageTag=(tags||[]).find(t=>String(t).startsWith('yas:')),age=ageTag?String(ageTag).slice(4):'',warnings=(tags||[]).filter(t=>String(t).startsWith('uyari:')).map(t=>String(t).slice(6));return{age,warnings}}
function enhanceContentSettings(){const form=$('#bookEditForm');if(!form)return;const meta=contentMeta(manageState.book.tags),message=$('#bookEditMessage');message.insertAdjacentHTML('beforebegin',`<section class="content-settings"><h3>Yaş ve içerik bilgisi</h3><p>Okurun hikâyeye başlamadan önce göreceği uyarıları belirle.</p><label>Yaş derecelendirmesi<select id="contentAge"><option value="">Belirtilmedi</option>${['Herkes','13+','16+','18+'].map(age=>`<option ${meta.age===age?'selected':''}>${age}</option>`).join('')}</select></label><label>İçerik uyarıları<input id="contentWarnings" maxlength="250" value="${esc(meta.warnings.join(', '))}" placeholder="Şiddet, zorbalık, kendine zarar verme…"></label><button type="button" class="ghost" data-save-content-settings>Uyarıları kaydet</button><span id="contentSettingsMessage"></span></section>`)}
async function saveContentSettings(){const age=$('#contentAge')?.value||'',warnings=($('#contentWarnings')?.value||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,8),base=(manageState.book.tags||[]).filter(t=>!String(t).startsWith('yas:')&&!String(t).startsWith('uyari:')),tags=[...base,...(age?[`yas:${age}`]:[]),...warnings.map(x=>`uyari:${x}`)],message=$('#contentSettingsMessage');message.textContent='Kaydediliyor…';try{await sb(`/rest/v1/stories?id=eq.${manageState.book.id}`,{method:'PATCH',body:{tags}});manageState.book.tags=tags;const listed=stories.find(s=>s.id===manageState.book.id);if(listed)listed.tags=tags;message.textContent='İçerik bilgileri kaydedildi.'}catch(err){message.textContent=err.message}}

async function deleteBook(id,title){if(!confirm(`“${title}” kitabını ve tüm fasıllarını kalıcı olarak silmek istiyor musun?`))return;try{await sb(`/rest/v1/stories?id=eq.${id}&author_id=eq.${session.user.id}`,{method:'DELETE'});await loadStories();accountDialog.close();await openAccount()}catch(err){alert('Kitap silinemedi: '+err.message)}}
async function openAuthor(id){authorDialog.showModal();$('#authorView').innerHTML='<p class="reader-loading">Yazar sayfası yükleniyor…</p>';try{const [profile,works,followers,following]=await Promise.all([sb(`/rest/v1/profiles?select=id,display_name,username,bio&id=eq.${id}`),sb(`/rest/v1/stories?select=id,title,summary,genre,read_count,author_id&author_id=eq.${id}&visibility=eq.public&order=published_at.desc`),sb(`/rest/v1/follows?select=follower_id&followed_id=eq.${id}`),session?sb(`/rest/v1/follows?select=followed_id&followed_id=eq.${id}&follower_id=eq.${session.user.id}`):Promise.resolve([])]),p=profile?.[0],mapped=(works||[]).map(w=>stories.find(s=>s.id===w.id)||{id:w.id,live:true,authorId:id,title:w.title,author:p?.display_name||'Fasl yazarı',genre:w.genre,reads:String(w.read_count||0),likes:'0',color:'#17251f',accent:'#b36a44'});if(!p)throw new Error('Yazar bulunamadı.');$('#authorView').innerHTML=`<div class="author-profile"><div class="profile-avatar">${esc(p.display_name[0].toUpperCase())}</div><h2>${esc(p.display_name)}</h2><span>@${esc(p.username)}</span><p>${esc(p.bio||'Hikâyelerini Fasl’da paylaşan bir anlatıcı.')}</p><b>${followers?.length||0} takipçi</b>${session?.user?.id!==id?`<button class="ink" data-follow="${id}">${following?.length?'Takibi bırak':'Takip et'}</button>`:''}</div><h3 class="author-books-title">Yazarın kitapları</h3><div class="story-grid author-books">${storyCards(mapped)}</div>`}catch(err){$('#authorView').innerHTML=`<p class="reader-loading">${esc(err.message)}</p>`}}
async function toggleFollow(id){if(!requireSession())return;const existing=await sb(`/rest/v1/follows?select=followed_id&followed_id=eq.${id}&follower_id=eq.${session.user.id}`);if(existing?.length)await sb(`/rest/v1/follows?followed_id=eq.${id}&follower_id=eq.${session.user.id}`,{method:'DELETE'});else await sb('/rest/v1/follows',{method:'POST',body:{followed_id:id,follower_id:session.user.id}});renderFollowFeed();authorDialog.close();await openAuthor(id)}
async function updateNotificationCount(){const badge=$('#notificationCount');if(!session){badge.hidden=true;return}try{const unread=await sb(`/rest/v1/notifications?select=id&user_id=eq.${session.user.id}&read_at=is.null`);badge.textContent=unread?.length||0;badge.hidden=!unread?.length}catch{badge.hidden=true}}
async function openNotifications(){if(!requireSession())return;notificationsDialog.showModal();$('#notificationsView').innerHTML='Bildirimler yükleniyor…';try{const rows=await sb(`/rest/v1/notifications?select=id,title,body,story_id,read_at,created_at&user_id=eq.${session.user.id}&order=created_at.desc&limit=50`);$('#notificationsView').innerHTML=rows?.length?rows.map(n=>`<button ${n.story_id?`data-story="${n.story_id}"`:''} class="${n.read_at?'':'unread'}"><b>${esc(n.title)}</b><span>${esc(n.body)}</span><time>${new Date(n.created_at).toLocaleString('tr-TR')}</time></button>`).join(''):'<p>Henüz bildirimin yok.</p>';if(rows?.some(n=>!n.read_at))await sb(`/rest/v1/notifications?user_id=eq.${session.user.id}&read_at=is.null`,{method:'PATCH',body:{read_at:new Date().toISOString()}});updateNotificationCount()}catch(err){$('#notificationsView').innerHTML=`<p>${esc(err.message)}</p>`}}
async function openNotificationsV2(){if(!requireSession())return;notificationsDialog.showModal();$('#notificationsView').innerHTML='Bildirimler yükleniyor…';try{const rows=await sb(`/rest/v1/notifications?select=id,title,body,story_id,chapter_id,read_at,created_at&user_id=eq.${session.user.id}&order=created_at.desc&limit=50`);$('#notificationsView').innerHTML=rows?.length?`<div class="notification-toolbar"><b>Bildirimlerin</b>${rows.some(n=>!n.read_at)?'<button class="text-btn" data-read-all-notifications>Tümünü okundu işaretle</button>':''}</div>${rows.map(n=>`<button ${n.story_id?`data-notification-story="${n.story_id}" data-notification-chapter="${n.chapter_id||''}" data-notification-id="${n.id}"`:''} class="${n.read_at?'':'unread'}"><b>${esc(n.title)}</b><span>${esc(n.body)}</span><time>${new Date(n.created_at).toLocaleString('tr-TR')}</time></button>`).join('')}`:'<p>Henüz bildirimin yok.</p>'}catch(err){$('#notificationsView').innerHTML=`<p>${esc(err.message)}</p>`}}
async function openNotificationStory(button){if(button.dataset.notificationId)await sb(`/rest/v1/notifications?id=eq.${button.dataset.notificationId}&user_id=eq.${session.user.id}`,{method:'PATCH',body:{read_at:new Date().toISOString()}});notificationsDialog.open&&notificationsDialog.close();await openStory(button.dataset.notificationStory);const chapterId=button.dataset.notificationChapter,index=chapterId?readerState?.chapters?.findIndex(c=>c.id===chapterId):-1;if(index>=0)openReadingPage(index);updateNotificationCount()}
