async function openAdmin(){if(!currentProfile?.is_admin)return;accountDialog.close();adminDialog.showModal();$('#adminView').innerHTML='Yönetim verileri yükleniyor…';try{const [reports,comments,notifications,profiles]=await Promise.all([sb('/rest/v1/reports?select=id,reporter_id,target_type,target_id,reason,status,created_at&order=created_at.desc&limit=100'),sb('/rest/v1/chapter_comments?select=id,user_id,message,created_at&order=created_at.desc&limit=100'),sb('/rest/v1/notifications?select=id,user_id,title,body,created_at&order=created_at.desc&limit=100'),sb('/rest/v1/profiles?select=id,display_name')]),names=Object.fromEntries((profiles||[]).map(p=>[p.id,p.display_name]));$('#adminView').innerHTML=`<div class="admin-stats"><b>${reports?.filter(r=>r.status==='open').length||0}<small>Açık itiraz</small></b><b>${comments?.length||0}<small>Son yorum</small></b><b>${notifications?.length||0}<small>Bildirim</small></b></div><div class="admin-columns"><section><h3>İtirazlar</h3>${reports?.length?reports.map(r=>`<article><b>${esc(names[r.reporter_id]||'Kullanıcı')}</b><span>${esc(r.reason)}</span><small>${esc(r.status)}</small>${r.status==='open'?`<button data-close-report="${r.id}">İncelendi olarak işaretle</button>`:''}</article>`).join(''):'<p>İtiraz yok.</p>'}</section><section><h3>Yorumlar</h3>${comments?.length?comments.map(c=>`<article><b>${esc(names[c.user_id]||'Kullanıcı')}</b><span>${esc(c.message)}</span><button class="danger-button" data-admin-delete-comment="${c.id}">Yorumu sil</button></article>`).join(''):'<p>Yorum yok.</p>'}</section><section><h3>Bildirimler</h3>${notifications?.length?notifications.map(n=>`<article><b>${esc(names[n.user_id]||'Kullanıcı')}</b><span>${esc(n.title)}</span><small>${new Date(n.created_at).toLocaleDateString('tr-TR')}</small></article>`).join(''):'<p>Bildirim yok.</p>'}</section></div>`}catch(err){$('#adminView').innerHTML=`<p>${esc(err.message)}</p>`}}
async function openAdminV2(){if(!currentProfile?.is_admin)return;accountDialog.open&&accountDialog.close();if(!adminDialog.open)adminDialog.showModal();$('#adminView').innerHTML='Yönetim verileri yükleniyor…';try{const [reports,comments,notifications,profiles]=await Promise.all([sb('/rest/v1/reports?select=id,reporter_id,target_type,target_id,reason,status,created_at&order=created_at.desc&limit=100'),sb('/rest/v1/chapter_comments?select=id,user_id,message,created_at&order=created_at.desc&limit=100'),sb('/rest/v1/notifications?select=id,user_id,title,created_at&order=created_at.desc&limit=100'),sb('/rest/v1/profiles?select=id,display_name')]),names=Object.fromEntries((profiles||[]).map(p=>[p.id,p.display_name])),storyNames=Object.fromEntries(stories.map(s=>[s.id,s.title])),statusName={open:'Açık',reviewed:'İncelendi',closed:'Kapatıldı'};$('#adminView').innerHTML=`<div class="admin-stats"><b>${reports?.filter(r=>r.status==='open').length||0}<small>Açık itiraz</small></b><b>${reports?.filter(r=>r.status==='reviewed').length||0}<small>İncelenen</small></b><b>${comments?.length||0}<small>Son yorum</small></b></div><div class="admin-columns"><section><h3>İtirazlar</h3>${reports?.length?reports.map(r=>`<article class="report-${r.status}"><div class="admin-row"><b>${esc(names[r.reporter_id]||'Kullanıcı')}</b><em>${statusName[r.status]||r.status}</em></div><small>${r.target_type==='story'?'Hikâye':'Yorum'} · ${new Date(r.created_at).toLocaleDateString('tr-TR')}</small>${r.target_type==='story'?`<strong>${esc(storyNames[r.target_id]||'Bildirilen hikâye')}</strong>`:''}<span>${esc(r.reason)}</span><div class="admin-actions">${r.target_type==='story'?`<button data-admin-open-story="${r.target_id}">İçeriği aç</button>`:''}${r.status==='open'?`<button data-close-report="${r.id}">İncelendi</button>`:''}${r.status!=='closed'?`<button data-resolve-report="${r.id}">Kapat</button>`:`<button data-reopen-report="${r.id}">Yeniden aç</button>`}</div></article>`).join(''):'<p>İtiraz yok.</p>'}</section><section><h3>Son yorumlar</h3>${comments?.length?comments.map(c=>`<article><b>${esc(names[c.user_id]||'Kullanıcı')}</b><small>${new Date(c.created_at).toLocaleDateString('tr-TR')}</small><span>${esc(c.message)}</span><button class="danger-button" data-admin-delete-comment="${c.id}">Yorumu kaldır</button></article>`).join(''):'<p>Yorum yok.</p>'}</section><section><h3>Bildirim geçmişi</h3>${notifications?.length?notifications.map(n=>`<article><b>${esc(names[n.user_id]||'Kullanıcı')}</b><span>${esc(n.title)}</span><small>${new Date(n.created_at).toLocaleDateString('tr-TR')}</small></article>`).join(''):'<p>Bildirim yok.</p>'}</section></div>`}catch(err){$('#adminView').innerHTML=`<p>${esc(err.message)}</p>`}}
