render();renderRankings();loadStories();updateSessionUi();
document.addEventListener('click',async e=>{
  const infoLink=e.target.closest('a[href="#kosullar"],a[href="#topluluk-kurallari"],a[href="#gizlilik"],a[href="#yardim"]');if(infoLink){e.preventDefault();openInfoPage(infoLink.getAttribute('href').slice(1));return}
  const notification=e.target.closest('[data-notification-story]');if(notification){e.preventDefault();await openNotificationStory(notification);return}
  if(e.target.closest('[data-read-all-notifications]')){await markAllNotificationsRead();return}
  const resumeStory=e.target.closest('[data-resume-story]');if(resumeStory){e.preventDefault();e.stopPropagation();libraryDialog.open&&libraryDialog.close();accountDialog.open&&accountDialog.close();await openStory(resumeStory.dataset.resumeStory);if(readerState?.chapters?.length)openReadingPage(Math.max(0,readerState.resumeIndex||0));return}
  const author=e.target.closest('[data-author]');if(author){e.preventDefault();openAuthor(author.dataset.author);return}
  const card=e.target.closest('[data-story]');if(card){e.preventDefault();[libraryDialog,accountDialog,notificationsDialog,authorDialog].forEach(d=>d.open&&d.close());openStory(card.dataset.story)}
  const manage=e.target.closest('[data-manage]');if(manage)openManage(manage.dataset.manage,manage.dataset.tab);
  const manageTab=e.target.closest('[data-manage-tab]');if(manageTab)renderManage(manageTab.dataset.manageTab);
  const deleteButton=e.target.closest('[data-delete-book]');if(deleteButton)deleteBook(deleteButton.dataset.deleteBook,deleteButton.dataset.bookTitle);
  if(e.target.closest('[data-remove-cover]'))removeBookCover();
  if(e.target.closest('[data-save-content-settings]'))saveContentSettings();
  if(e.target.closest('[data-new-story]')){writeDialog._returnDialog=accountDialog;accountDialog.close();writeDialog.showModal()}
  const startReading=e.target.closest('[data-start-reading]');if(startReading)openReadingPage(Number(startReading.dataset.startReading)||0);
  const chapterChoice=e.target.closest('[data-chapter-index]');if(chapterChoice)openReadingPage(Number(chapterChoice.dataset.chapterIndex),Number(chapterChoice.dataset.chapterIndex)>readerState.index?'turn-forward':'turn-back');
  if(e.target.closest('[data-notifications]'))openNotificationsV2();
  if(e.target.closest('[data-admin]')){adminDialog._returnDialog=accountDialog;openAdminV2()}
  const follow=e.target.closest('[data-follow]');if(follow)toggleFollow(follow.dataset.follow);
  const report=e.target.closest('[data-report-comment]');if(report)reportComment(report.dataset.reportComment);
  const storyReport=e.target.closest('[data-report-story]');if(storyReport)reportStory(storyReport.dataset.reportStory);
  const closeReport=e.target.closest('[data-close-report]');if(closeReport){await updateReportStatus(closeReport.dataset.closeReport,'reviewed')}
  const resolveReport=e.target.closest('[data-resolve-report]');if(resolveReport){await updateReportStatus(resolveReport.dataset.resolveReport,'closed')}
  const reopenReport=e.target.closest('[data-reopen-report]');if(reopenReport){await updateReportStatus(reopenReport.dataset.reopenReport,'open')}
  const adminStory=e.target.closest('[data-admin-open-story]');if(adminStory){adminDialog.close();openStory(adminStory.dataset.adminOpenStory)}
  const deleteComment=e.target.closest('[data-admin-delete-comment]');if(deleteComment&&confirm('Bu yorumu silmek istiyor musun?')){await sb(`/rest/v1/chapter_comments?id=eq.${deleteComment.dataset.adminDeleteComment}`,{method:'DELETE'});adminDialog.close();openAdminV2()}
  if(e.target.closest('[data-auth],[data-account]')){e.preventDefault();session?openAccount():authDialog.showModal()}
  if(e.target.closest('[data-library]')){e.preventDefault();openLibrary()}
  if(e.target.closest('[data-write]'))session?writeDialog.showModal():authDialog.showModal();
  if(e.target.matches('[data-close]'))closeDialogToPrevious(e.target.closest('dialog'));
  if(e.target.closest('[data-reader-close]'))closeBookPage();
  if(e.target.closest('[data-reading-close]'))closeReadingPage();
  if(e.target.closest('[data-info-close]'))closeInfoPage();
  if(e.target.closest('[data-prev]')&&!e.target.disabled){readerState.index--;readingMode?openReadingPage(readerState.index,'turn-back'):renderReader('turn-back')}
  if(e.target.closest('[data-next]')&&!e.target.disabled){readerState.index++;readingMode?openReadingPage(readerState.index,'turn-forward'):renderReader('turn-forward')}
  if(e.target.closest('[data-like]'))toggleLike();if(e.target.closest('[data-save]'))toggleLibrary();
  if(e.target.closest('[data-session-login]')){clearSession();accountDialog.close();authDialog.showModal();$('#authMessage').textContent='Oturumun sona erdi. Lütfen tekrar giriş yap.'}
  if(e.target.closest('[data-logout]')){clearSession();accountDialog.close()}
  if(e.target.closest('#closeSearch,.brand,a[href="#kesfet"]'))exitSearch()
});
