function resizeCover(file){return new Promise((resolve,reject)=>{if(!['image/jpeg','image/png','image/webp'].includes(file.type))return reject(new Error('Lütfen JPG, PNG veya WebP görsel seç.'));if(file.size>8*1024*1024)return reject(new Error('Kapak dosyası 8 MB’dan küçük olmalı.'));const reader=new FileReader();reader.onerror=()=>reject(new Error('Görsel okunamadı.'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error('Görsel açılamadı.'));image.onload=()=>{const canvas=document.createElement('canvas'),width=600,height=840,scale=Math.max(width/image.width,height/image.height),sourceWidth=width/scale,sourceHeight=height/scale,sourceX=(image.width-sourceWidth)/2,sourceY=(image.height-sourceHeight)/2;canvas.width=width;canvas.height=height;canvas.getContext('2d').drawImage(image,sourceX,sourceY,sourceWidth,sourceHeight,0,0,width,height);let result=canvas.toDataURL('image/jpeg',.82);if(result.length>700000)result=canvas.toDataURL('image/jpeg',.65);resolve(result)};image.src=reader.result};reader.readAsDataURL(file)})}
function resizeCoverUncropped(file){return new Promise((resolve,reject)=>{if(!['image/jpeg','image/png','image/webp'].includes(file.type))return reject(new Error('Lütfen JPG, PNG veya WebP görsel seç.'));if(file.size>8*1024*1024)return reject(new Error('Kapak dosyası 8 MB’dan küçük olmalı.'));const reader=new FileReader();reader.onerror=()=>reject(new Error('Görsel okunamadı.'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error('Görsel açılamadı.'));image.onload=()=>{const scale=Math.min(1,900/image.width,1200/image.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);let result=canvas.toDataURL('image/jpeg',.84);if(result.length>700000)result=canvas.toDataURL('image/jpeg',.68);resolve(result)};image.src=reader.result};reader.readAsDataURL(file)})}
