let draftTimer,chapterDraftTimer;const draftText=$('#draftText'),saveState=$('#saveState');function savedTime(){return new Date().toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'})}function saveDraft(){localStorage.setItem('fasl-draft',JSON.stringify({title:$('#draftTitle').value,genre:$('#draftGenre').value,tags:$('#draftTags').value,text:draftText.value,savedAt:Date.now()}));saveState.textContent=`${savedTime()} kaydedildi`}function queueDraftSave(){saveState.textContent='Kaydediliyor…';clearTimeout(draftTimer);draftTimer=setTimeout(saveDraft,700)}$('#saveDraft').onclick=saveDraft;$('#writeForm').addEventListener('input',()=>{const words=draftText.value.trim()?draftText.value.trim().split(/\s+/).length:0;$('#wordCount').textContent=`${words} kelime`;queueDraftSave()});
